// Files that help AI assistants (ChatGPT, Claude, Gemini, Perplexity, Copilot…) find and quote the clinic correctly:
//  - robots.txt naming the AI crawlers explicitly (public pages open, private areas closed)
//  - llms.txt: a short, structured guide to the site (llmstxt.org)
//  - llms-full.txt: the full text of every public page and article in plain Markdown
// Generated by `npm run build` from the built pages, so they always match the website.
import fs from "node:fs";
import path from "node:path";
import { root, SITE } from "./partials.js";

const PRIVATE = ["/admin", "/api/", "/manage.html", "/checkin.html"];
// Search engines and AI assistants (search, answer and training crawlers) that may read the public pages.
const BOTS = [
  "*", "Googlebot", "Bingbot", "Google-Extended", "GPTBot", "OAI-SearchBot", "ChatGPT-User", "ClaudeBot", "Claude-SearchBot",
  "Claude-User", "PerplexityBot", "Perplexity-User", "Applebot", "Applebot-Extended", "DuckAssistBot", "meta-externalagent",
  "Amazonbot", "CCBot", "YandexBot",
];

export function writeRobots() {
  const lines = [
    "# Public pages may be read by search engines and AI assistants; private areas may not.",
    ...BOTS.map((b) => `User-agent: ${b}`),
    "Allow: /",
    ...PRIVATE.map((p) => `Disallow: ${p}`),
    "",
    `Sitemap: ${SITE}/sitemap.xml`,
    "",
    `# Plain-text guide for AI assistants: ${SITE}/llms.txt`,
    "",
  ];
  fs.writeFileSync(path.join(root, "public/robots.txt"), lines.join("\n"));
}

const decode = (s) => s.replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&rarr;/g, "→");

/** Main content of a built page as simple Markdown (headings, paragraphs, lists, definition lists, links). */
export function pageToMarkdown(html) {
  let m = (/<main[^>]*>([\s\S]*?)<\/main>/.exec(html) || [, html])[1];
  m = m
    .replace(/<(script|style|svg|form|noscript|button|template)\b[\s\S]*?<\/\1>/g, "")
    .replace(/<figure class="anim"[\s\S]*?<figcaption>([\s\S]*?)<\/figcaption>\s*<\/figure>/g, "<p>$1</p>")
    .replace(/<div[^>]*\bhidden\b[^>]*>[\s\S]*?<\/div>/g, "")
    .replace(/<(span|div)[^>]*aria-hidden="true"[^>]*>[\s\S]*?<\/\1>/g, "")
    .replace(/<div class="(feature__icon|explore__icon|globe)"[^>]*>[\s\S]*?<\/div>/g, "")
    .replace(/<li[^>]*>([\s\S]*?)<\/li>/g, (all, inner) => (/<h[1-6]\b/.test(inner) ? inner : `\n- ${inner}`))
    .replace(/<h1[^>]*>([\s\S]*?)<\/h1>/g, "\n# $1\n")
    .replace(/<h2[^>]*>([\s\S]*?)<\/h2>/g, "\n## $1\n")
    .replace(/<h3[^>]*>([\s\S]*?)<\/h3>/g, "\n### $1\n")
    .replace(/<summary[^>]*>([\s\S]*?)<\/summary>/g, "\n### $1\n")
    .replace(/<dt[^>]*>([\s\S]*?)<\/dt>\s*<dd[^>]*>([\s\S]*?)<\/dd>/g, "\n- **$1:** $2")
    .replace(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/g, "\n> $1\n")
    .replace(/<(p|figcaption|address)[^>]*>([\s\S]*?)<\/\1>/g, "\n$2\n")
    .replace(/<br\s*\/?>/g, ", ")
    .replace(/<a [^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g, (all, href, label) => {
      const t = label.replace(/<[^>]+>/g, "").trim();
      if (!t || href.startsWith("#")) return t;
      return `[${t}](${href.startsWith("/") ? SITE + href : href})`;
    })
    .replace(/<strong[^>]*>([\s\S]*?)<\/strong>/g, "**$1**")
    .replace(/<[^>]+>/g, " ");
  return decode(m)
    .split("\n").map((l) => l.replace(/[ \t]+/g, " ").trim()).filter((l, i, a) => l || (a[i - 1] && a[i - 1].trim()))
    .join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

export function writeLlms(allPages, posts) {
  const pages = allPages.filter((p) => p.lang !== "hi"); // the English pages (the Hindi ones say the same)
  const page = (p) => fs.readFileSync(path.join(root, "public", p.file), "utf8");
  const link = (p) => `${SITE}${p.slug}`;
  const short = `# Tailbone Treatment Clinic

> Specialist, non-surgical treatment for tailbone (coccyx) pain, also called coccydynia or coccygodynia, led by Dr Rajveer Singh (BPT, Fellowship in Orthopaedic Rehabilitation, Apollo Hospital Chennai). Clinic in Vasant Kunj, New Delhi, India, plus online video consultations worldwide. Lucknow clinic opening soon. The Bengaluru clinic has closed.

Key facts:
- Conditions treated: coccydynia (tailbone pain), subluxed or dislocated coccyx, tailbone pain after a fall or injury, after pregnancy or childbirth, pain when sitting, chronic tailbone discomfort.
- Approach: assessment and diagnosis, hands-on Internal Manipulation of the coccyx and surrounding muscles, posture and seating advice, exercises and follow-up. Surgery is rarely needed.
- Address: 150A/09, Shanti Apartment, Kishangarh, Vasant Kunj, New Delhi 110070, India.
- Hours (by appointment): Monday–Friday 10:00–17:00, Saturday 10:00–15:00, Sunday 08:00–15:00 (IST).
- Fees: consultation ₹800 (in clinic or online); follow-up within 7 days ₹500.
- Book: ${SITE}/book · WhatsApp or phone +91 98866 88323 · contact@tailbonetreatment.com
- Medical information on this site is general and not a substitute for an examination.

## Main pages

${pages.map((p) => `- [${p.title}](${link(p)}): ${p.description}`).join("\n")}

## Articles

${posts.map(({ meta }) => `- [${meta.title}](${SITE}/blog/${meta.slug}.html): ${meta.summary}`).join("\n")}

## In the news

- [Newspaper coverage of Dr Rajveer Singh's tailbone pain work](${SITE}/press.html): The Times of India, Deccan Herald, Hindustan (Delhi), Rajasthan Patrika, Prajavani and others, 2013–2016.

## Optional

- [Full text of this site in one file](${SITE}/llms-full.txt)
- [Patient stories](${SITE}/stories.html)
- [Terms, fees, cancellation and refund policy](${SITE}/policies.html)
- [Privacy notice](${SITE}/privacy.html)
`;
  const full = [
    short.replace(/\n## Main pages[\s\S]*$/, "").trim(),
    ...pages.filter((p) => p.page !== "book").map((p) => `\n\n---\n\nSource: ${link(p)}\n\n${pageToMarkdown(page(p))}`),
    ...posts.map(({ meta, body }) => `\n\n---\n\nSource: ${SITE}/blog/${meta.slug}.html (published ${meta.date})\n\n# ${meta.title}\n\n${meta.summary}\n\n${body.replace(/^::anim .*$/gm, "").replace(/\n{3,}/g, "\n\n").trim()}`),
  ].join("");
  fs.writeFileSync(path.join(root, "public/llms.txt"), short);
  fs.writeFileSync(path.join(root, "public/llms-full.txt"), `${full}\n`);
}
